-- Nagrand: creature abilities
-- Most of the zone's creatures (the Boulderfist and Warmaul ogres, the Murkblood, the elementals, talbuks and clefthoofs) had no AI
-- or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows needing
-- events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The creatures no
-- reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '16945,17128,17129,17130,17131,17132,17133,17136,17137,17138,17139,17141,17144,17151,17152,17153,17154,17155,17158,17159,17160,18065,18069,18180,18202,18203,18204,18205,18207,18220,18226,18229,18257,18261,18289,18290,18297,18298,18334,18352,18391,18399,18413,18414,18415,18423,18440,18535,18536,18567,18660,18661,18683,18684,18688,19067,19201,19210,22357,23026';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '18033,18192,18238,18256,18396,22309,22310,22311,22313';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
